<?php
declare(strict_types=1); require_once __DIR__.'/../app/bootstrap.php'; require_admin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$product=(int)($_POST['product_id']??0);$qty=(float)($_POST['quantity']??0);$type=$_POST['movement_type']??'';$reason=trim((string)($_POST['reason']??''));if($qty<=0||!in_array($type,['entry','exit','adjustment_in','adjustment_out'],true))throw new RuntimeException();$pdo->beginTransaction();$s=$pdo->prepare('SELECT stock_quantity FROM products WHERE id=? FOR UPDATE');$s->execute([$product]);$r=$s->fetch();if(!$r)throw new RuntimeException();$before=(float)$r['stock_quantity'];$incoming=in_array($type,['entry','adjustment_in'],true);$after=$incoming?$before+$qty:$before-$qty;if($after<0)throw new RuntimeException('Stock insuficiente.');$pdo->prepare('UPDATE products SET stock_quantity=? WHERE id=?')->execute([$after,$product]);$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,movement_type,quantity,stock_before,stock_after,reason) VALUES(?,?,?,?,?,?,?)')->execute([$product,(int)current_user()['id'],$type,$qty,$before,$after,$reason]);$pdo->commit();flash('Movimento de stock registado.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Não foi possível registar. Confirme o produto, quantidade e stock disponível.','error');}redirect('stock.php');}
$products=$pdo->query('SELECT id,name,stock_quantity,unit FROM products WHERE active=1 ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT sm.*,p.name product_name,u.name user_name FROM stock_movements sm JOIN products p ON p.id=sm.product_id LEFT JOIN users u ON u.id=sm.user_id ORDER BY sm.id DESC LIMIT 100')->fetchAll();layout_start('Movimentos de stock');echo '<section class="panel"><h2>Registar entrada ou saída</h2><form method="post">'.csrf_field().'<div class="form-grid"><div class="field"><label>Produto</label><select name="product_id" required><option value="">Selecionar produto</option>';foreach($products as $p)echo '<option value="'.(int)$p['id'].'">'.e($p['name']).' — stock: '.e($p['stock_quantity']).' '.e($p['unit']).'</option>';echo '</select></div><div class="field"><label>Tipo</label><select name="movement_type" required><option value="entry">Entrada</option><option value="exit">Saída</option><option value="adjustment_in">Ajuste positivo</option><option value="adjustment_out">Ajuste negativo</option></select></div><div class="field"><label>Quantidade</label><input name="quantity" type="number" min="0.001" step="0.001" required></div><div class="field"><label>Motivo</label><input name="reason" maxlength="255" placeholder="Ex.: compra ao fornecedor"></div></div><button>Registar movimento</button></form></section><section class="panel"><h2>Últimos 100 movimentos</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Quantidade</th><th>Antes</th><th>Depois</th><th>Responsável</th><th>Motivo</th></tr></thead><tbody>';if(!$rows)echo '<tr><td colspan="8" class="empty">Sem movimentos registados.</td></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['created_at']).'</td><td>'.e($r['product_name']).'</td><td>'.e($r['movement_type']).'</td><td>'.e($r['quantity']).'</td><td>'.e($r['stock_before']).'</td><td>'.e($r['stock_after']).'</td><td>'.e($r['user_name']??'—').'</td><td>'.e($r['reason']).'</td></tr>';echo '</tbody></table></div></section>';layout_end();
